def json_escape(s: str) -> str:
    result = ['"']
    for ch in s:
        cp = ord(ch)
        if ch == '"':
            result.append('\\"')
        elif ch == '\\':
            result.append('\\\\')
        elif ch == '\n':
            result.append('\\n')
        elif ch == '\t':
            result.append('\\t')
        elif ch == '\r':
            result.append('\\r')
        elif ch == '\b':
            result.append('\\b')
        elif ch == '\f':
            result.append('\\f')
        elif cp < 0x20:
            result.append('\\u' + format(cp, '04x'))
        else:
            result.append(ch)
    result.append('"')
    return ''.join(result)

